import type { Seed } from './roadmap-build';

// "Databases & data modeling" learning path — 120 questions (15 levels × 8),
// easiest → hardest: relational basics, SQL, schema design & normalization,
// keys/constraints, indexing, transactions/ACID, the N+1 problem, NoSQL and
// scaling. Built directly (ids rm-db-1 … rm-db-120, 8 per level).
export const databasesSeeds: Seed[] = [
  // Level 1 — What is a Database?
  { q: 'An application must store customer records after the process restarts, query them by several fields, and update them safely. What is the usual foundation?', opts: ['A log file that the application scans from the beginning for every request', 'A database designed to persist, query, and update structured data', 'A programming language that keeps every record in local variables', 'A web server cache with no durable backing store'], a: 1, e: 'A database gives all three properties at once: data that outlives the process, indexed lookup on several fields, and controlled concurrent updates. A log file scanned from the start does persist the data but cannot query it by field without reading everything; local variables vanish with the process; a cache with no durable backing store is a copy, not a system of record.', tags: ['Databases', 'basics'], intro: 'Ask what each option still holds after the machine reboots, and how it would find one customer among a million.' },
  { q: 'PostgreSQL controls storage, queries, transactions, permissions, and recovery for a database. What kind of software is it?', opts: ['A backup scheduler only', 'A database management system (DBMS)', 'A distributed in-memory cache', 'An object-relational mapper'], a: 1, e: 'A database management system owns storage, query execution, transactions, access control and crash recovery; PostgreSQL is one. An ORM maps rows to objects inside your application and still needs a DBMS underneath, a cache holds derived copies with no durability guarantee, and a backup scheduler only moves data around.', intro: 'The listed jobs all belong to one layer. Ask which option is that layer rather than a tool that sits beside it.', tags: ['Databases', 'DBMS'] },
  { q: 'Which is a relational database?', opts: ['Redis', 'MongoDB', 'PostgreSQL', 'Neo4j'], a: 2, e: 'PostgreSQL is the relational (SQL) engine: data lives in tables with typed columns, constraints and joins. Redis is an in-memory data store addressed by key, MongoDB stores JSON-like documents, and Neo4j stores nodes and edges for graph traversal; each has a query interface, but none of them is relational.', intro: 'Sort the four names by data model: key-value, document, graph, table.', tags: ['Databases', 'relational'] },
  { q: 'A relational model stores one customer per record and the same fields for each customer. How is that usually represented?', opts: ['A table of rows and columns', 'A folder per field with one file per value', 'One deeply nested document for the entire company', 'A queue that removes each record after it is read'], a: 0, e: 'A table (relation) has a fixed set of typed columns and one row per record, so every customer has the same fields and can be queried by any of them. A folder per field has no schema and no query language, one nested document for the whole company mixes unrelated records together, and a queue is consumed rather than stored.', intro: 'Every customer carries the same fields. Ask which shape gives every record identical slots.', tags: ['Databases', 'tables'] },
  { q: 'A process stores shopping carts only in an in-memory map. What property is missing when every cart disappears after a restart?', opts: ['Normalization, because the carts are not split into related tables', 'Persistence, because the data does not outlive the running process', 'Indexing, because lookup becomes slower after a restart', 'Replication, because each process needs its own independent copy'], a: 1, e: 'Persistence means the data outlives the process that wrote it, which a plain in-memory map cannot do; a database or another disk-backed store provides it. Normalization is about how data is split across tables, indexing is about lookup speed, and replication adds copies for availability - a restart still wipes every replica that only lives in memory.', intro: 'The map worked correctly while the process was up. Ask which of the four terms is a guarantee about storage rather than about table layout or lookup speed.', tags: ['Databases', 'persistence'] },
  { q: 'An API lets clients create an order, retrieve it, change its address, and remove it. Which shorthand names those four basic data operations?', opts: ['CRUD: Create, Read, Update, Delete', 'ACID: Atomicity, Consistency, Isolation, Durability', 'DDL: the SQL commands that define a schema', 'ETL: Extract, Transform, Load'], a: 0, e: 'CRUD names the four record-level operations - create, read, update, delete - which is exactly what the API exposes, in any language or protocol. ACID names transaction guarantees, DDL is the SQL subset that defines schema objects, and ETL describes moving data between systems; none of the three names those four actions.', intro: 'Ask which acronym lists actions performed on one record, rather than transaction guarantees or pipeline stages.', tags: ['Databases', 'CRUD'] },
  { q: 'You need to join orders to customers and aggregate totals inside a relational database. Which language is designed for that query?', opts: ['GraphQL', 'SQL', 'JSONPath', 'Prisma Client'], a: 1, e: 'SQL is the language relational engines execute: the join and the aggregation happen inside the database, and the planner decides how. GraphQL queries an API you have to implement, JSONPath addresses parts of a JSON value, and Prisma Client is a TypeScript library that generates SQL for you - useful, but not the query language the engine speaks.', intro: 'The join and the aggregation run inside the engine. Ask what the engine itself parses, rather than what a client library or an API layer emits.', tags: ['Databases', 'SQL'] },
  { q: 'A migration adds an `orders.total_cents` integer column and a foreign key to `customers`. What part of the database is it changing?', opts: ['The latest backup snapshot', 'The schema: tables, columns, types, constraints, and relationships', 'One customer record in the application cache', 'The server’s network address and connection pool'], a: 1, e: 'A migration edits the schema: the definitions of tables, columns, types, constraints, indexes and relationships that every row must then satisfy. It does not touch a backup snapshot, a cached copy inside the application, or the server\'s address and pool settings - those live outside the database\'s structural definitions.', intro: 'After this migration every future row must carry an integer total and point at a real customer. Ask where that permanent requirement lives.', tags: ['Databases', 'schema'] },

  // Level 2 — Relational Basics
  { q: 'In a table, a "row" represents:', opts: ['A single field', 'A single record/entity instance', 'The table name', 'A database connection'], a: 1, e: 'A row (tuple) is one record - one user, one order - carrying a value for each of the table\'s columns. A single field is one cell, the intersection of a row and a column; the table name and a database connection are not data in the table at all.', intro: 'Picture the grid: this slice cuts across every column. What does one such slice describe?', tags: ['Databases', 'rows'] },
  { q: 'A "column" in a table represents:', opts: ['One record', 'An attribute/field shared by every row', 'A foreign server', 'An index'], a: 1, e: 'A column defines one attribute - email, created_at - and every row carries a value for it, possibly NULL. One record is a row; an index is a separate structure built over a column to speed up lookups, not the column itself; a foreign server is not part of the table.', intro: 'Think of `email` in a users table. Ask what `email` itself is, and what an index built on `email` would be instead.', tags: ['Databases', 'columns'] },
  { q: 'What is a primary key?', opts: ['Any column that allows duplicates', 'A column (or set) that uniquely identifies each row in a table', 'The first column alphabetically', 'A password for the table'], a: 1, e: 'A primary key uniquely identifies each row and cannot be NULL or duplicated.', tags: ['Databases', 'primary key'] },
  { q: 'What is a foreign key?', opts: ['A key from another database vendor', 'A column that references the primary key of another table to link them', 'A duplicate primary key', 'An encrypted column'], a: 1, e: 'A foreign key references another table’s primary key, enforcing a relationship and referential integrity.', tags: ['Databases', 'foreign key'] },
  { q: 'The orders table has a user_id column referencing users.id, and nothing stops two orders from naming the same user. Which relationship does that model?', opts: ['One-to-one', 'One-to-many', 'Many-to-many', 'Self-referencing'], a: 1, e: 'Many order rows may carry the same user_id and each order names exactly one user, so this is one-to-many, modeled the usual way with the foreign key on the many side. One-to-one would need a unique constraint on orders.user_id, many-to-many would need a third table holding both keys, and self-referencing would mean the foreign key pointed back at the same table.', intro: 'Ask how many orders may share one user_id, and how many users a single order may name.', tags: ['Databases', 'relationships'] },
  { q: 'A many-to-many relationship (e.g. students and courses) is usually modeled with:', opts: ['A single table', 'A junction/join table holding both foreign keys', 'Two primary keys in one row', 'No table at all'], a: 1, e: 'Both sides repeat, so neither table can hold a single foreign key to the other; the pair gets its own table - enrollments(student_id, course_id), one row per student-course pairing. Keeping it in one table would duplicate one side\'s data on every pairing, and a row cannot carry two independent primary keys.', intro: 'A student takes several courses and a course holds several students. Ask where one foreign-key column could store that.', tags: ['Databases', 'many-to-many'] },
  { q: 'What does "referential integrity" ensure?', opts: ['Every foreign key value points to an existing row', 'Every column is indexed', 'All data is encrypted', 'Queries always run fast'], a: 0, e: 'Referential integrity means every foreign-key value matches an existing row in the referenced table: the database rejects an insert or update pointing at nothing, and blocks or cascades a delete that would orphan rows. Indexing, encryption and query speed are separate properties - Postgres does not even index the referencing column automatically, so integrity and performance are decisions you make separately.', intro: 'Ask which writes the database starts refusing once the constraint exists.', tags: ['Databases', 'integrity'] },
  { q: 'Which best describes a "relation" in relational theory?', opts: ['A foreign key', 'A table', 'A network link', 'A stored procedure'], a: 1, e: 'In relational theory a relation is a table: a set of tuples that all share the same attributes. The trap is reading \'relation\' as \'relationship\' - links between tables are expressed by foreign keys, not by this word. A stored procedure is code stored in the database, and a network link is not part of the model at all.', intro: 'The word looks like \'relationship\', but relational theory uses it for something else. Ask what the model\'s basic data structure is called.', tags: ['Databases', 'theory'] },

  // Level 3 — SQL SELECT Basics
  { q: 'Which clause retrieves data from a table?', opts: ['GET', 'SELECT', 'FETCH', 'READ'], a: 1, e: 'SELECT is the SQL statement used to read rows from one or more tables.', tags: ['SQL', 'select'] },
  { q: 'How do you select every column from a table named users?', opts: ['SELECT all FROM users', 'SELECT * FROM users', 'GET * IN users', 'SELECT columns(users)'], a: 1, e: 'SELECT * FROM users returns every column of every row: * is the wildcard for the column list and FROM names the table. The other three are not SQL. In application code, naming the columns you need is usually better, because a later ALTER TABLE can otherwise change the shape of a result your code already depends on.', intro: 'Only one of these four is valid SQL. Check each word against the two clauses every row-reading query needs.', tags: ['SQL', 'select'] },
  { q: 'Which clause limits which rows are returned based on a condition?', opts: ['FILTER', 'HAVING', 'WHERE', 'ONLY'], a: 2, e: 'WHERE tests each row before grouping and drops the ones that fail: WHERE age >= 18. HAVING is the real alternative, but it runs after GROUP BY and tests aggregates. Postgres does have a FILTER clause, which narrows the input of one aggregate rather than the rows the query returns, and ONLY controls table inheritance, not filtering.', intro: 'One of the other options also filters, but only after rows have been grouped. Which one runs on individual rows?', tags: ['SQL', 'where'] },
  { q: 'What does SELECT name FROM users WHERE id = 5 return?', opts: ['Every name in the users table', 'The name of each row whose id is 5', 'The id of each row whose name is 5', 'Nothing, because the statement is invalid'], a: 1, e: 'The select list picks the name column, FROM names the table, and WHERE keeps only rows whose id is 5 - usually a single row, since id is normally the primary key. Returning every name would mean dropping the WHERE clause, and swapping the roles of name and id would need a different statement; nothing here is invalid syntax.', intro: 'Read the statement in three parts: which columns, which table, which rows.', tags: ['SQL', 'where'] },
  { q: 'How do you return a column\'s values with duplicates removed?', opts: ['SELECT UNIQUE col', 'SELECT DISTINCT col', 'SELECT ONLY col', 'SELECT col GROUP'], a: 1, e: 'SELECT DISTINCT col removes duplicate rows from the result. It applies to the whole select list, so SELECT DISTINCT city, country removes duplicate city-country pairs, not duplicates of each column separately. UNIQUE is a table constraint rather than a select modifier, and the other two are not SQL.', intro: 'The keyword sits right after SELECT and acts on what you selected. Recall the spelling SQL actually defines.', tags: ['SQL', 'distinct'] },
  { q: 'Which keyword gives a column or table a different name in the result (an alias)?', opts: ['AS', 'RENAME', 'ALIAS', 'CALL'], a: 0, e: 'AS creates an alias: SELECT price AS cost FROM products AS p. It renames only the output column or the table reference inside that one query, while RENAME belongs to ALTER TABLE and changes the stored schema. Postgres lets you drop AS before a column alias, but only when the alias is not a keyword, so writing AS is the safer habit.', intro: 'Aliases are written inline in the select list or the FROM list, not with a command that changes the stored schema.', tags: ['SQL', 'alias'] },
  { q: 'What does LIMIT 10 do?', opts: ['Skips 10 rows', 'Returns at most 10 rows', 'Deletes 10 rows', 'Requires exactly 10 rows'], a: 1, e: 'LIMIT 10 returns at most ten rows, and fewer if the query produces fewer; it never deletes rows or requires an exact count, and skipping rows is OFFSET\'s job. Without an ORDER BY that fixes a unique order, which ten rows come back is unpredictable and can change between runs.', intro: 'Learners often confuse this clause with OFFSET. Recall what OFFSET does, then decide what is left for this one.', tags: ['SQL', 'limit'] },
  { q: 'Which combination paginates results (skip then take)?', opts: ['SKIP and TAKE', 'OFFSET and LIMIT', 'PAGE and SIZE', 'START and END'], a: 1, e: 'OFFSET skips rows and LIMIT caps how many follow, so OFFSET 20 LIMIT 10 is the third page of ten; Postgres also accepts the SQL-standard FETCH FIRST 10 ROWS ONLY. SKIP/TAKE and PAGE/SIZE come from ORMs and HTTP APIs, not from SQL. Deep offsets get slow because the engine still walks and discards every skipped row, so keyset pagination (WHERE id > :last_id ORDER BY id LIMIT 10) scales better, though it gives up jumping straight to an arbitrary page.', intro: 'One keyword decides where the window starts, the other how wide it is. Name them in that order.', tags: ['SQL', 'pagination'] },

  // Level 4 — Filtering & Sorting
  { q: 'How do you sort results by a column ascending?', opts: ['SORT col', 'ORDER BY col ASC', 'ARRANGE col', 'GROUP BY col'], a: 1, e: 'ORDER BY col ASC sorts ascending; ASC is the default, so ORDER BY col means the same thing and DESC reverses it. GROUP BY collapses rows into groups for aggregation and promises no output order at all, which is why a grouped query still needs its own ORDER BY. SORT and ARRANGE are not SQL keywords.', intro: 'One of the answers also rearranges rows, but it collapses them into groups instead of putting them in order.', tags: ['SQL', 'order by'] },
  { q: 'Which operator matches a pattern, e.g. names starting with "A"?', opts: ['MATCH', 'LIKE', 'REGEX', 'CONTAINS'], a: 1, e: 'LIKE compares a value against a pattern in which % matches any run of characters and _ matches exactly one, so WHERE name LIKE \'A%\' finds names starting with A. In Postgres LIKE is case-sensitive: use ILIKE for a case-insensitive match, or the ~ operator when you need a real regular expression.', intro: 'Recall which operator takes the wildcards % and _.', tags: ['SQL', 'like'] },
  { q: 'What does WHERE age BETWEEN 18 AND 30 match?', opts: ['Ages 19 to 29', 'Ages 18 to 30 inclusive', 'Only 18 and 30', 'Ages over 30'], a: 1, e: 'BETWEEN a AND b expands to age >= 18 AND age <= 30, so both endpoints match and 18 and 30 are included; excluding them would need the comparisons written out. Watch this with timestamps: created_at BETWEEN \'2026-01-01\' AND \'2026-01-31\' stops at midnight and silently drops almost all of January 31.', intro: 'Decide whether the two endpoint values themselves pass the test.', tags: ['SQL', 'between'] },
  { q: 'How do you match any of several values, e.g. status is active, pending, or closed?', opts: ['WHERE status = \'active\', \'pending\', \'closed\'', 'WHERE status IN (\'active\', \'pending\', \'closed\')', 'WHERE status CONTAINS (\'active\', \'pending\', \'closed\')', 'WHERE status LIKE (\'active\', \'pending\', \'closed\')'], a: 1, e: 'IN tests set membership and is equivalent to three equality tests joined by OR. A comma list after = is not valid SQL, LIKE compares against one pattern at a time, and CONTAINS is not a Postgres operator. Take care with the negative form: if the list can contain NULL, NOT IN evaluates to unknown and returns no rows at all.', intro: 'You want one predicate that tests membership in a set, not three comparisons written out by hand.', tags: ['SQL', 'in'] },
  { q: 'How do you find rows where a column has no value?', opts: ['WHERE col = NULL', 'WHERE col IS NULL', 'WHERE col == NULL', 'WHERE col EMPTY'], a: 1, e: 'SQL uses three-valued logic, so col = NULL evaluates to unknown rather than true and the row is dropped: the query returns nothing and raises no error, which is what makes the bug quiet. IS NULL is the dedicated test. SQL has no == operator and no EMPTY keyword, and an empty string is a value, not NULL.', intro: 'NULL means unknown. Ask what \'unknown = unknown\' can possibly evaluate to.', tags: ['SQL', 'null'] },
  { q: 'Which operator completes the filter so it returns only paid orders created on or after 2026-01-01?\n\n```sql\nWHERE status = \'paid\' ___ created_at >= \'2026-01-01\'\n```', opts: ['OR', 'AND', 'NOT', 'XOR'], a: 1, e: 'AND keeps a row only when both predicates are true. OR keeps it when either is true, so it would also return paid orders from 2025 and unpaid orders created in 2026. NOT is unary and cannot join two predicates, and Postgres has no XOR operator - compare booleans with <> when you need exclusive-or.', intro: 'Check what each connector does to a row that satisfies only one of the two tests.', tags: ['SQL', 'logic'] },
  { q: 'What does ORDER BY created_at DESC do?', opts: ['Oldest first', 'Newest (largest) first', 'Random order', 'Alphabetical by id'], a: 1, e: 'DESC sorts from the largest value downward, and the largest timestamp is the most recent one, so the newest rows come first; ascending (the default) puts the oldest first. Nothing about DESC randomizes rows or switches to another column. If the column is nullable, add NULLS LAST - under DESC Postgres sorts nulls first.', intro: 'DESC and ASC differ only in direction. Work out which end of a timestamp range a descending sort puts first.', tags: ['SQL', 'order by'] },
  { q: "WHERE name LIKE '%son' matches names that:", opts: ['Start with son', 'End with son', 'Contain exactly son', 'Have no son'], a: 1, e: 'A leading % matches any prefix and the pattern then ends at \'son\', so only names ending in \'son\' match - Anderson, Jackson. \'son%\' would match names starting with son and \'%son%\' would match it anywhere in the string. In Postgres LIKE is case-sensitive, so a name ending in \'Son\' would not match this pattern.', intro: 'The wildcard sits on the left. Decide which end of the string the pattern pins down.', tags: ['SQL', 'like'] },

  // Level 5 — Aggregations & GROUP BY
  { q: 'Which aggregate reports how many rows a query matched?', opts: ['COUNT(*)', 'SUM(price)', 'AVG(price)', 'MAX(price)'], a: 0, e: 'COUNT(*) returns the number of input rows, whatever the columns contain. SUM, AVG and MAX summarize the values in one column and say nothing about how many rows produced them - SUM(price) over ten cheap rows can equal SUM(price) over two expensive ones. Use COUNT(col) only when you specifically want rows where col is not null.', intro: 'Ask whether you need a fact about the values inside a column or a fact about how many rows there are.', tags: ['SQL', 'aggregate'] },
  { q: 'Which aggregate returns the total of the numeric values in a column?', opts: ['COUNT(price)', 'SUM(price)', 'AVG(price)', 'MAX(price)'], a: 1, e: 'SUM(price) adds the non-null values and returns the total. COUNT(price) reports how many rows have a price, AVG divides that total by that count, and MAX returns the single largest value. One gotcha: SUM over zero matching rows returns NULL rather than 0, so wrap it in COALESCE when a number is required.', intro: 'Decide whether you need the values combined into one total, or a fact about their number or their size.', tags: ['SQL', 'aggregate'] },
  { q: 'What does GROUP BY do?', opts: ['Sorts the rows by the listed columns', 'Collapses rows with equal values into one row per group', 'Removes duplicate columns from the result', 'Joins two tables on the listed columns'], a: 1, e: 'GROUP BY buckets rows by the grouping columns and emits one row per bucket, so COUNT, SUM and friends are computed inside each bucket. It is not a sort - the output order is unspecified without ORDER BY - and it neither drops columns nor joins tables. Every column in the select list must therefore be grouped or wrapped in an aggregate, except that Postgres also allows a column functionally dependent on a grouped primary key.', intro: 'Aggregates like COUNT and SUM need something to compute over. Ask what this clause hands them.', tags: ['SQL', 'group by'] },
  { q: 'To count orders per user you would:', opts: ['SELECT COUNT(*) FROM orders', 'SELECT user_id, COUNT(*) FROM orders GROUP BY user_id', 'SELECT user_id FROM orders LIMIT 1', 'ORDER BY user_id'], a: 1, e: 'Grouping by user_id creates one bucket per user and COUNT(*) counts the rows in each, giving one row per user with their order count. COUNT(*) without GROUP BY collapses the whole table into a single number, LIMIT 1 returns one arbitrary row, and ORDER BY only sorts what is already there.', intro: 'Sketch what each query returns: how many rows, and does each row carry the user it belongs to?', tags: ['SQL', 'group by'] },
  { q: 'Which clause filters groups after aggregation (e.g. only users with > 5 orders)?', opts: ['WHERE', 'HAVING', 'FILTER', 'GROUP WHERE'], a: 1, e: 'HAVING runs after GROUP BY, so it can test aggregates: HAVING COUNT(*) > 5. WHERE runs first, on individual rows, and cannot see COUNT(*). Postgres does have FILTER, but it narrows the input of one aggregate - COUNT(*) FILTER (WHERE status = \'paid\') - instead of dropping whole groups, and GROUP WHERE is not SQL.', intro: 'The threshold is on a count, and that count does not exist until rows have been grouped. Which clause runs after that?', tags: ['SQL', 'having'] },
  { q: 'What does AVG(price) return?', opts: ['The largest price', 'The arithmetic mean of price', 'The number of prices', 'The smallest price'], a: 1, e: 'AVG(price) adds the non-null prices and divides by how many non-null prices there were - the arithmetic mean. Rows where price is NULL are skipped entirely, so AVG is not SUM(price)/COUNT(*) whenever nulls exist: 660 over five priced rows out of six is 132, not 110. MIN, MAX and COUNT are the functions the other options describe.', intro: 'The function name is short for one specific statistic. Ask which rows it divides by.', tags: ['SQL', 'aggregate'] },
  { q: 'Which pair of functions returns the smallest and the largest value in a column?', opts: ['MIN() and MAX()', 'COUNT() and SUM()', 'LOWER() and UPPER()', 'FLOOR() and CEIL()'], a: 0, e: 'MIN() and MAX() are aggregates: they scan the column and return its smallest and largest value, ignoring nulls. COUNT and SUM are aggregates too, but they report how many values there are and their total. LOWER/UPPER change the case of one string and FLOOR/CEIL round one number - both work row by row and never look across the column.', intro: 'You need two functions that scan the whole column, not ones that transform a single value.', tags: ['SQL', 'aggregate'] },
  { q: 'Why does COUNT(col) sometimes differ from COUNT(*)?', opts: ['They are always equal', 'COUNT(col) ignores rows where col is NULL', 'COUNT(*) ignores NULLs', 'COUNT(col) counts columns'], a: 1, e: 'COUNT(*) counts input rows; COUNT(col) counts only rows where col is not null, so the two differ by exactly the number of nulls in that column. That is a quiet reporting bug: COUNT(email) on a table with optional emails undercounts users and no error is raised. COUNT(*) never skips nulls, and neither form counts columns.', intro: 'Picture a users table where half the rows have no email. Work out what each of the two forms would report.', tags: ['SQL', 'count', 'null'] },

  // Level 6 — Joins
  { q: 'What does a JOIN do?', opts: ['Sorts one table by a related column', 'Combines rows from two tables on a matching column', 'Deletes rows that have no related row', 'Renames a table for the rest of the query'], a: 1, e: 'A JOIN pairs rows from two tables wherever the join condition is true - usually a foreign key matching a primary key - and returns the combined columns. It changes neither table: nothing is sorted, deleted or renamed by joining. A row that matches several rows on the other side appears once per match, which is why joins can multiply the row count.', intro: 'A JOIN is written with an ON condition. Ask what that condition decides about which rows end up side by side.', tags: ['SQL', 'joins'] },
  { q: 'An INNER JOIN returns:', opts: ['All rows from both tables', 'Only rows with a match in both tables', 'Only unmatched rows', 'Rows from the left table only'], a: 1, e: 'INNER JOIN keeps only pairs where the condition matched, so any row without a partner vanishes from the result - an inner join to users silently hides orders whose user_id points at a deleted user, and the total looks smaller than the table. Keeping all rows from both tables is FULL OUTER JOIN, and keeping every left row is LEFT JOIN.', intro: 'Ask what happens to a row on one side that finds no partner on the other.', tags: ['SQL', 'inner join'] },
  { q: 'A LEFT JOIN returns:', opts: ['Only the rows that matched on both sides', 'Every left row, with NULLs where the right side has no match', 'Every right row, with NULLs where the left side has no match', 'Only the left rows that had no match on the right'], a: 1, e: 'LEFT OUTER JOIN keeps every row of the left table and fills the right table\'s columns with NULL where nothing matched, which is how you find users with no orders: WHERE o.id IS NULL. Only matched rows is INNER JOIN and keeping every right row is RIGHT JOIN. Beware of putting a right-table condition in WHERE instead of ON - that discards the NULL-filled rows and quietly makes the join inner.', intro: 'Decide two things separately: which table keeps all of its rows, and what fills the gaps where nothing matched.', tags: ['SQL', 'left join'] },
  { q: 'Which join condition typically connects orders to users?', opts: ['orders.user_id = users.id', 'orders.id = users.id', 'orders.name = users.name', 'orders.* = users.*'], a: 0, e: 'orders.user_id is the foreign key holding a users.id value, so that equality is the join condition. Matching orders.id to users.id compares two unrelated identifier sequences and returns coincidental pairs that mean nothing; matching names is unreliable because names are neither unique nor stable; and orders.* = users.* is not valid SQL.', intro: 'Ask what orders.id counts, and whether two tables\' id values have any reason to line up.', tags: ['SQL', 'joins'] },
  { q: 'What does a CROSS JOIN produce?', opts: ['Only the rows that match on both sides', 'Every left row paired with every right row', 'An error, because no join condition is given', 'The rows of both tables stacked together'], a: 1, e: 'CROSS JOIN returns the Cartesian product: every row of one table paired with every row of the other, so 4 users and 6 orders give 24 rows. It is valid SQL rather than an error, and it is not a UNION, which stacks rows of the same shape instead of pairing them. Most accidental row explosions are a join whose ON condition was forgotten or matched the wrong column.', intro: 'A CROSS JOIN has no ON clause, and SQL does not reject it. Decide what it must do with the rows instead.', tags: ['SQL', 'cross join'] },
  { q: 'A "self join" is:', opts: ['Joining a table to itself (e.g. employees to their managers)', 'Joining two unrelated databases', 'A join that never returns rows', 'A join without a condition'], a: 0, e: 'A self join lists one table twice under different aliases - FROM employees e JOIN employees m ON e.manager_id = m.id - because without the aliases no column reference could say which copy it means. It matches rows of a table to other rows of the same table, which is how hierarchies are queried. Joining two separate databases is a different problem, and a join with no condition is a cross join.', intro: 'Ask what the word \'self\' has to refer to here, then check which option matches that reading.', tags: ['SQL', 'self join'] },
  { q: 'Why prefer a JOIN over running many separate queries in a loop?', opts: ['It always returns fewer rows than the loop does', 'It fetches the related rows in one round trip instead of many', 'SQL forbids querying the same table more than once', 'It removes the need for a foreign key between the tables'], a: 1, e: 'One join sends a single statement and lets the planner fetch the matching rows together, while the loop pays a round trip per row - the N+1 pattern, whose cost is latency rather than work. Treat it as a trade-off, not a rule: joining a one-to-many relation repeats the parent\'s columns on every child row, and a second batched query (WHERE user_id = ANY($1)) is often the cleaner fix. Row counts settle nothing either way, since an inner join drops unmatched rows and a one-to-many join multiplies them, and SQL never requires a join at all.', intro: 'Picture the first query returning 500 rows, then count what the loop sends to the database next.', tags: ['SQL', 'joins', 'performance'] },
  { q: 'A FULL OUTER JOIN returns:', opts: ['Only the rows that matched on both sides', 'Every row of both tables, NULL-filled where unmatched', 'Every left row plus its matches from the right', 'Every right row plus its matches from the left'], a: 1, e: 'FULL OUTER JOIN keeps every row from both tables, pairing them where the condition matched and filling the absent side\'s columns with NULL, which makes it the join for reconciling two sets: the unmatched rows are the ones where one side\'s key IS NULL. Keeping one side\'s rows is LEFT or RIGHT JOIN and keeping only matches is INNER JOIN. Postgres supports it; MySQL does not, so ported queries often emulate it with a UNION.', intro: 'Start from the word FULL and compare it with LEFT and RIGHT. Ask which rows each of the three is allowed to drop.', tags: ['SQL', 'outer join'] },

  // Level 7 — Schema Design & Normalization
  { q: 'What is the goal of normalization?', opts: ['To store each fact in one place and avoid update anomalies', 'To make every query faster by removing joins', 'To reduce the number of tables in the schema', 'To guarantee that no column is ever NULL'], a: 0, e: 'Normalization splits data so each fact lives in exactly one place, which removes the update, insert and delete anomalies that duplicated facts cause. It usually adds joins rather than removing them, and it tends to increase the table count, so it is a consistency decision with a query cost - not a speed optimization. It says nothing about NULLs, and deliberately reintroducing redundancy for read speed is denormalization.', intro: 'Normalization is not free: it changes what a query has to do. Ask what it buys in return.', tags: ['Databases', 'normalization'] },
  { q: 'First normal form (1NF) requires that:', opts: ['Every column holds a single atomic value (no repeating groups/arrays)', 'There are no foreign keys', 'Every table has exactly one column', 'Data is denormalized'], a: 0, e: '1NF asks that a column hold one value per row rather than a repeating group - not tags packed into a comma-separated string, and not phone1/phone2/phone3 columns - because you cannot filter, join or constrain part of a field reliably. Foreign keys, table count and denormalization are unrelated to it. A Postgres array or jsonb column is a deliberate exception, taken when the value is always read and written as a whole.', intro: 'Look at what a single column may hold, not at how many tables the schema has.', tags: ['Databases', '1NF'] },
  { q: 'An orders table repeats the customer\'s current mailing address on every order row, and that address must always show where the customer lives now. What does the design risk?', opts: ['Update anomalies: changing the address means editing many rows', 'Referential integrity errors, because the address has no foreign key', 'Slower reads, because every order must join to customers', 'Wasted indexes, because an address column cannot be indexed'], a: 0, e: 'When one fact is stored in many rows, every change has to reach every copy, and one missed row makes the data disagree with itself - the update anomaly. The design does not break referential integrity or indexing, and it makes reads faster, not slower, since no join is needed. Note the opposite case: when the address is a historical fact of the order - where it actually shipped - copying it in is correct, because it must not change when the customer moves.', intro: 'The same fact now lives in many rows. Ask what happens on the day it changes.', tags: ['Databases', 'anomalies'] },
  { q: 'A "surrogate key" is:', opts: ['A natural attribute already in the data, such as email', 'A generated identifier with no business meaning, such as an id', 'A foreign key pointing at another table\'s primary key', 'A key derived by hashing several of the row\'s columns'], a: 1, e: 'A surrogate key is generated by the system only to identify the row - an identity/serial integer or a UUID - so it never has to change when business facts change. A natural key such as email is meaningful but mutable and sometimes unknown, a foreign key identifies a row in a different table, and a hash of columns changes whenever those columns do. In Postgres, prefer GENERATED ALWAYS AS IDENTITY over the older serial notation.', intro: 'Think about what must happen to every referencing row when a customer changes the email you keyed on.', tags: ['Databases', 'keys'] },
  { q: 'When is denormalization (deliberate redundancy) reasonable?', opts: ['When reads dominate and the extra write and consistency cost is acceptable', 'Never, because redundancy always violates referential integrity', 'Only in schemas that have not reached first normal form', 'Only for columns that are part of a primary key'], a: 0, e: 'Denormalization duplicates or precomputes data to make a hot read path cheaper, and the price is paid on every write: more rows to touch and a real chance that copies drift apart. It is a measured trade-off, reached for after a query plan shows the join or aggregate is the bottleneck - and often better served by a materialized view or a cache. Redundancy does not violate referential integrity, and no normal form gates the decision.', intro: 'Ask what evidence would justify this before you write it, and what you would have to keep checking afterwards.', tags: ['Databases', 'denormalization'] },
  { q: 'Third normal form (3NF) removes:', opts: ['All foreign keys', 'Transitive dependencies (non-key columns depending on other non-key columns)', 'Primary keys', 'Indexes'], a: 1, e: '3NF requires every non-key column to depend on the key alone. If orders stores customer_id, customer_city and city_population, the population is a fact about the city rather than about the order - a transitive dependency, fixed by moving it to a cities table. Foreign keys, primary keys and indexes are not what any normal form removes.', intro: 'Picture an orders table that also stores the customer\'s city and that city\'s population. Ask which of those facts is about the order.', tags: ['Databases', '3NF'] },
  { q: 'An app stores customers and their orders. Which schema keeps the data consistent and queryable as it grows?', opts: ['One wide table repeating the customer\'s columns on every order', 'A customers table and an orders table linked by a foreign key', 'One table per customer, created when that customer signs up', 'One JSON document per customer holding all of their orders'], a: 1, e: 'Customers and orders are distinct entities with different lifetimes, so each gets a table and orders carries a foreign key to customers: the customer\'s details are stored once and their orders are still one join away. Repeating customer columns per order duplicates the same fact, a table per customer forces every cross-customer query to union one table per customer, and a document per customer is workable for whole-document reads but gives up joins, per-order constraints and cheap aggregates.', intro: 'Ask what each design costs you when a customer is renamed, and when you need every order placed last Tuesday.', tags: ['Databases', 'modeling'] },
  { q: 'A junction table for a many-to-many relationship typically has:', opts: ['A foreign key to each side, usually as a composite primary key', 'A single foreign key to whichever table is larger', 'Copies of every column from both related tables', 'Only its own generated id, with the links stored elsewhere'], a: 0, e: 'The junction table holds one foreign key per side - enrollments(student_id, course_id) - and making the pair the primary key both identifies the row and stops the same student being enrolled in the same course twice. A single foreign key can only express one side, copying all the columns recreates the duplication the table exists to avoid, and a bare id would link nothing. Attributes of the pairing itself, such as enrolled_at, belong here too.', intro: 'Ask what the table must contain to record a link, and what stops the same link appearing twice.', tags: ['Databases', 'modeling'] },

  // Level 8 — Keys & Constraints
  { q: 'A UNIQUE constraint guarantees:', opts: ['Values can repeat', 'No two rows share the same value(s) in that column', 'The column is the primary key', 'The column is indexed but not unique'], a: 1, e: 'UNIQUE makes the database reject any insert or update that repeats a value in the constrained column or column set, which is how an email column stays one-per-account. Nulls are the exception: Postgres treats two nulls as distinct, so several rows may leave the column empty unless the constraint says NULLS NOT DISTINCT. It is not the primary key - a table may have many unique constraints and a unique column may be nullable - though Postgres does enforce it with a unique index.', intro: 'Decide what a second insert with the same value does - and whether a missing value counts as the same value.', tags: ['Databases', 'constraints'] },
  { q: 'A NOT NULL constraint means:', opts: ['The column may still hold NULL in some rows', 'The column must always have a value', 'The column is the primary key', 'The column auto-increments'], a: 1, e: 'NOT NULL rejects any insert or update that leaves the column unset, so every row must supply a value. An empty string, 0 and false are values and still pass, which is why NOT NULL alone does not mean \'meaningful\' - add a CHECK when the empty case matters. A primary key implies NOT NULL, but NOT NULL by itself neither makes a key nor generates values.', intro: '\'No value\' and \'an empty value\' are not the same thing here. Which one does the constraint forbid?', tags: ['Databases', 'constraints'] },
  { q: 'A CHECK constraint is used to:', opts: ['Encrypt a column', 'Enforce a condition on values (e.g. price >= 0)', 'Create an index', 'Join two tables'], a: 1, e: 'A CHECK constraint attaches a boolean condition to the table, and any insert or update that makes it false is rejected: CHECK (price >= 0) keeps negative prices out no matter which service wrote the row. Encryption, indexing and joining are separate features and none of them validates values. A CHECK sees only the row being written, so cross-row rules need UNIQUE, a foreign key or a trigger instead.', intro: 'The word \'constraint\' is the clue. Ask what the database can be made to refuse on your behalf.', tags: ['Databases', 'constraints'] },
  { q: 'What does ON DELETE CASCADE do for a foreign key?', opts: ['Deletes the referencing rows when the referenced row is deleted', 'Blocks the delete while referencing rows still exist', 'Sets the referencing rows\' foreign key to NULL instead', 'Copies the referencing rows before the delete happens'], a: 0, e: 'ON DELETE CASCADE deletes the child rows along with the parent, so no row is left referencing a missing key. The other options are the remaining referential actions: NO ACTION (the default) and RESTRICT raise an error instead, and SET NULL clears the child\'s foreign key. Cascades are silent and can remove far more than intended, so use them only where a child has no meaning without its parent.', intro: 'Deleting a parent would leave its children pointing at nothing. Ask which of the possible outcomes this clause picks.', tags: ['Databases', 'cascade'] },
  { q: 'A composite key is:', opts: ['A key made of two or more columns together', 'A single column that stores several values joined by a separator', 'A foreign key that references two different tables', 'A primary key that the database generates automatically'], a: 0, e: 'A composite (compound) key is two or more columns whose combined values identify a row, which is why a join table is usually keyed on (order_id, product_id) rather than on either column alone. Packing several values into one column with a separator looks similar but is the opposite: the database can no longer compare, constrain or index the parts. A composite key may also serve as a foreign key, but that is a separate role, and no part of it has to be database-generated.', intro: 'Count how many columns take part in the uniqueness rule, not what the key is used for.', tags: ['Databases', 'keys'] },
  { q: 'A DEFAULT on a column:', opts: ['Replaces any NULL written to the column with the default value', 'Supplies a value automatically when an INSERT omits the column', 'Requires every INSERT to state the column explicitly', 'Creates an index on the column so lookups are faster'], a: 1, e: 'DEFAULT fills the column only when the INSERT leaves it out (or writes the DEFAULT keyword), which is why created_at DEFAULT now() populates itself. Writing NULL explicitly stores NULL: a default is not a NULL replacement, so pair it with NOT NULL when the column must always hold a value. It neither forces the column to appear in an INSERT nor creates any index.', intro: 'Ask what happens at INSERT time when the column is left out, and whether writing NULL yourself is the same thing.', tags: ['Databases', 'default'] },
  { q: 'You INSERT a row whose foreign key points at a parent that does not exist. What does the database do?', opts: ['Inserts the row and leaves the reference dangling', 'Rejects the statement with a foreign-key violation error', 'Inserts the row and creates the missing parent automatically', 'Stores the row but sets the foreign-key column to NULL'], a: 1, e: 'The foreign key is checked as the row is written, so the statement fails with a foreign-key violation and no row is stored. In PostgreSQL that error also leaves the surrounding transaction in a failed state until you ROLLBACK or return to a SAVEPOINT, so the rest of the transaction cannot simply continue. Nothing repairs the reference for you: the database will not invent a parent row, and it will not blank the column, since only an explicit ON DELETE SET NULL does that, and only when a parent is removed.', intro: 'Decide when the reference is checked, at write time or later, and what a failed check does to the statement.', tags: ['Databases', 'constraints'] },
  { q: 'Why add a UNIQUE constraint on email rather than just checking in app code?', opts: ['It avoids the extra SELECT, which is the real saving', 'The database enforces it atomically, so two concurrent inserts cannot both win', 'Application checks cannot see rows inserted by other requests', 'A constraint removes the need to handle a duplicate error in code'], a: 1, e: 'Check-then-insert has a gap: two requests can both read \'no such email\' and both insert, and no amount of application code closes that window on its own. The unique index is enforced at write time, so the second insert waits for the first transaction and fails once that transaction commits, whatever order the requests arrive in. An application check does see rows other requests have already committed; what it cannot see is an insert still in flight, which is exactly the window the constraint covers. Dropping the extra SELECT is a side benefit, not the reason, and you still have to catch the duplicate error and turn it into a usable message.', intro: 'Picture two requests running the check at the same instant and ask which layer can still tell them apart.', tags: ['Databases', 'constraints', 'concurrency'] },

  // Level 9 — Data Types & NULL
  { q: 'Which type best stores a monetary amount precisely?', opts: ['DOUBLE PRECISION, because it holds fractional values', 'NUMERIC(12,2), because it stores exact decimal digits', 'REAL, because it needs less storage than NUMERIC', 'TEXT, because the digits are kept exactly as written'], a: 1, e: 'NUMERIC/DECIMAL is fixed-point: 19.99 is stored as exact decimal digits, so sums, comparisons and rounding behave the way an accountant expects. Binary floating point (REAL, DOUBLE PRECISION) cannot represent most decimal fractions at all, which is why 0.1 + 0.2 = 0.3 evaluates to false and why cents drift as totals grow. TEXT does keep the digits exactly, but it gives you no arithmetic, no numeric ordering and no range check until you cast, so the exactness buys nothing.', intro: 'Ask which representation can hold 19.99 exactly and which one only gets close.', tags: ['Databases', 'types'] },
  { q: 'What does NULL represent?', opts: ['The number zero', 'An empty string', 'The absence of a value (unknown/not applicable)', 'A boolean false'], a: 2, e: 'NULL marks a value that is missing or unknown, so it is not 0, not \'\' and not false, all of which are known values you can compare and index on. Because it is unknown, any comparison with it returns unknown rather than true, which is why WHERE col = NULL matches nothing and IS NULL exists. The same rule explains why COUNT(col) skips NULLs while COUNT(*) counts the rows.', intro: 'Ask why SQL needs IS NULL instead of letting you test the column with = 0 or = \'\' like any other value.', tags: ['Databases', 'null'] },
  { q: 'What is NULL = NULL in SQL?', opts: ['TRUE', 'FALSE', 'NULL/unknown', 'An error'], a: 2, e: 'SQL uses three-valued logic: comparing anything with NULL yields unknown, which is itself NULL, so the result is neither TRUE nor FALSE. A WHERE clause keeps only rows whose condition is TRUE, so WHERE col = NULL matches nothing at all, and that is what IS NULL and IS NOT DISTINCT FROM are for. It is not an error either: the statement runs normally and simply returns no rows.', intro: 'Ask what the comparison can honestly report when neither side is a known value.', tags: ['Databases', 'null'] },
  { q: 'Which type is best for a true/false flag?', opts: ['CHAR(1) holding \'Y\' or \'N\'', 'BOOLEAN', 'SMALLINT holding 0 or 1', 'TEXT holding \'true\' or \'false\''], a: 1, e: 'BOOLEAN puts the domain in the schema: in PostgreSQL the column accepts true, false or NULL and rejects anything else, and queries read as WHERE is_active with no decoding convention. The character and integer encodings all admit values the column does not mean (\'y\', \'YES\', 2), so correctness then depends on every writer remembering the rule. MySQL is the exception worth knowing: BOOLEAN there is a synonym for TINYINT(1) and stores any integer, so the declaration records intent while a CHECK constraint does the enforcing.', intro: 'Think about what the next developer has to know before they can read this column\'s value correctly.', tags: ['Databases', 'types'] },
  { q: 'A TIMESTAMP WITH TIME ZONE column is preferable to a naive timestamp because:', opts: ['It uses less space', 'It records an unambiguous instant regardless of server time zone', 'It is faster to index', 'It cannot be NULL'], a: 1, e: 'In PostgreSQL, timestamptz converts the input to an absolute instant on write (stored as UTC) and renders it in the session time zone on read, so the same moment means the same thing to every server and client. A plain timestamp stores wall-clock digits with no zone, so a value like 2026-03-29 02:30 can be ambiguous or nonexistent depending on where it was written. Both types occupy 8 bytes and index identically, so storage and index speed are not the reason to pick one, and neither type says anything about NULL.', intro: 'Ask what a stored value means when the writer and the reader sit in different time zones.', tags: ['Databases', 'time'] },
  { q: 'COALESCE(col, 0) returns:', opts: ['0 for every row, because the second argument wins', 'col when col is not NULL, otherwise 0', 'NULL whenever col is NULL, because NULL spreads through functions', '0 when col is NULL or 0, because both count as empty'], a: 1, e: 'COALESCE returns its first argument that is not NULL, so a row with col = 5 returns 5 and a row with col = NULL returns 0. It is not an ordinary NULL-propagating expression like col + 0, which stays NULL, and it does not treat 0 as empty: only NULL triggers the fallback. In PostgreSQL the arguments must also share a common type, so COALESCE(col, 0) on a text column is a type error rather than a fallback.', intro: 'Take two rows, one with a value and one without, and work out what the expression returns for each.', tags: ['Databases', 'null', 'coalesce'] },
  { q: 'In PostgreSQL, choosing VARCHAR(50) vs TEXT mainly affects:', opts: ['How much disk space a short value occupies', 'A length limit on the value (TEXT is unbounded)', 'Whether the column can be indexed', 'Whether the column can hold NULL'], a: 1, e: 'In PostgreSQL varchar(n), varchar and text share one implementation and store a short string identically; the only practical difference is that varchar(n) rejects a value longer than n. So choose a limit when the domain has a genuine maximum, such as a two-letter country code, and expect a migration when the limit was only a guess. Storage, indexability and nullability do not change with the choice: NOT NULL and CREATE INDEX are separate decisions.', intro: 'Ask what the database refuses to store under one declaration but accepts under the other.', tags: ['Databases', 'types'] },
  { q: 'Storing a JSON document in a JSONB column is useful when:', opts: ['The rows are uniform and every field is filtered and joined on', 'The shape varies between rows but you still need to query and index fields inside it', 'You want the database to enforce which fields are present and what type they are', 'The values are numbers you mostly aggregate with SUM and AVG'], a: 1, e: 'JSONB earns its place when the shape genuinely varies per row, because you can still filter on fields and index them with a GIN or expression index. The cost is that the database no longer checks the shape: required fields and types are enforced only by whatever writes the row, and every reader has to tolerate missing keys. Uniform data that you filter, join and aggregate belongs in columns, so use JSONB for the parts that vary rather than as a way to skip schema design.', intro: 'Ask what the database can still do for you inside a document, and what it stops guaranteeing about one.', tags: ['Databases', 'json'] },

  // Level 10 — Indexing
  { q: 'What is the primary purpose of an index?', opts: ['It caches the results of recent queries so they can be replayed', 'It lets the database find matching rows without reading the whole table', 'It compresses the table so it occupies less disk space', 'It guarantees that the indexed column contains no NULLs'], a: 1, e: 'An index is a separate sorted structure, usually a B-tree, mapping key values to row locations, so a lookup or range scan touches a few pages instead of every row. That read speed is paid for with disk space and with extra work on every insert, update and delete that changes the key, which is why indexes are chosen per query rather than added everywhere. It is not a result cache, not compression, and it constrains values only when declared UNIQUE.', intro: 'An index is a separate copy of the key values with pointers to rows. Ask what that copy can and cannot do.', tags: ['Indexing', 'basics'] },
  { q: 'What is a common downside of adding many indexes?', opts: ['Reads on the indexed columns become slower', 'Writes slow down and storage grows, because every index has to be maintained', 'The planner stops using any index once there are several', 'Existing queries must be rewritten to name the index'], a: 1, e: 'Every index is a second structure the database must update inside each INSERT, UPDATE and DELETE that touches its key, and it occupies disk and cache next to the table. So an index is a trade rather than an improvement: one that serves a filter your application actually runs usually pays for itself, while one added just in case costs write throughput and space forever. Reads on the indexed columns get faster, not slower, and the planner chooses among available indexes per query without being named.', intro: 'Follow one row through an INSERT and count how many structures have to be updated.', tags: ['Indexing', 'tradeoffs'] },
  { q: 'A query filtering on WHERE email = ? is fastest when:', opts: ['email has no index', 'email is indexed', 'the table has no primary key', 'you SELECT *'], a: 1, e: 'An index on email lets the DB jump straight to matching rows instead of scanning every row.', tags: ['Indexing', 'where'] },
  { q: 'What data structure backs most general-purpose database indexes?', opts: ['A hash table, which is what makes range scans fast', 'A B-tree, which keeps keys sorted and the tree balanced', 'A linked list of row pointers in insertion order', 'A bitmap of matching row ids for every value'], a: 1, e: 'A B-tree keeps keys sorted and the tree balanced, so a lookup costs a few page reads and the same structure also serves range predicates, sorting and prefix matching. That breadth is why it is the default index type. A hash index answers equality only and cannot do ranges at all, and the specialized types (GIN, GiST, BRIN, bitmap structures) target particular data or query shapes rather than general use.', intro: 'Think about what an index has to support besides finding one exact value.', tags: ['Indexing', 'b-tree'] },
  { q: 'A composite index on (last_name, first_name) helps queries that filter:', opts: ['By first_name only', 'By last_name, or last_name then first_name (leftmost prefix)', 'By any column in any order equally', 'Only by primary key'], a: 1, e: 'A multicolumn B-tree is ordered by last_name first, so a filter on last_name, or on last_name and first_name together, can jump straight to the matching range. A filter on first_name alone has no leading value to seek to: PostgreSQL can still read the whole index if that beats reading the table, and since version 18 its skip scan can step through the last_name values when there are very few of them, but neither gives the range narrowing a leading-column filter gets. Column order is therefore a design decision: (last_name, first_name) and (first_name, last_name) serve different queries, and a query that filters only on first_name usually needs its own index.', intro: 'Think about how the entries are arranged inside the index before deciding which filters can use them.', tags: ['Indexing', 'composite'] },
  { q: 'EXPLAIN (or EXPLAIN ANALYZE) is used to:', opts: ['Rewrite the query into a faster equivalent form', 'Show the plan the database will use, so you can see whether an index is used', 'Report how many rows the query returned the last time it ran', 'Lock the tables the query touches so timings are reproducible'], a: 1, e: 'EXPLAIN prints the planner\'s chosen plan — sequential scan versus index scan, join order, estimated rows and cost — which is how you check whether an index is being used. EXPLAIN ANALYZE goes further and actually executes the statement to report real timings and row counts, so wrap it in BEGIN ... ROLLBACK when the statement writes. Neither form changes the query or the data by itself: the planner decides, and EXPLAIN only reports what it decided.', intro: 'You reach for it when a query is slow and you want to know why before changing anything.', tags: ['Indexing', 'explain'] },
  { q: 'A "full table scan" means:', opts: ['The database used an index but had to read every index entry', 'The database read every row in the table instead of narrowing the search with an index', 'The database copied the table to a temporary file before answering', 'The query returned every row in the table'], a: 1, e: 'A sequential (full) scan reads every row and applies the filter, so its cost tracks the size of the table rather than the number of matches — a query returning ten rows can still be a scan. The planner picks it when no usable index exists, but also when it estimates that most rows match or that the table is small enough for random index lookups to cost more. So a scan in EXPLAIN is a signal to check the table size and the estimated row count, not proof that an index is missing.', intro: 'Separate how many rows the database had to read from how many it ended up returning.', tags: ['Indexing', 'scan'] },
  { q: 'Compared with a plain index on the same column, a UNIQUE index also:', opts: ['Stores the column values twice so lookups are faster', 'Rejects any second row that repeats an existing value', 'Prevents the column from holding NULL', 'Forces the planner to use it for every query on that column'], a: 1, e: 'A unique index is an ordinary index plus a rule enforced on write: the second row carrying an existing key fails with a constraint violation. Lookups are no faster than with a plain index, although the planner can rely on there being at most one match. It says nothing about NULL — PostgreSQL treats two nulls as distinct, so a unique column accepts many null rows unless you add NOT NULL or declare NULLS NOT DISTINCT.', intro: 'Ask what changes at write time, not at read time, when the index is declared unique.', tags: ['Indexing', 'unique'] },

  // Level 11 — Transactions & ACID
  { q: 'What is a database transaction?', opts: ['A connection held open for as long as the application runs', 'A unit of work whose statements all commit or all roll back together', 'A copy of the affected rows taken before an update', 'A queue of statements the database runs when it is idle'], a: 1, e: 'A transaction groups statements so that either all of their effects apply or none do: COMMIT makes them visible together, ROLLBACK discards them together, and a crash in between leaves neither half. That is what lets a transfer debit one row and credit another with no moment where the money exists in neither. In PostgreSQL a statement sent outside BEGIN still runs inside its own implicit transaction, so the real question is not whether you have one but how much work you put inside it.', intro: 'Picture a transfer that debits one account and then crashes before it credits the other.', tags: ['Transactions', 'basics'] },
  { q: 'A server crashes midway through a transfer. After recovery the debit is present but the credit is not, although the transaction never committed. Which ACID property was violated?', opts: ['Consistency', 'Atomicity', 'Isolation', 'Durability'], a: 1, e: 'Atomicity is the all-or-nothing property: an uncommitted transaction must leave no trace after recovery, so a surviving debit without its credit is exactly an atomicity failure. Durability points the other way — it promises that work already committed survives the crash — and nothing here was committed. Consistency is about the database still satisfying its declared constraints, and isolation is about what concurrent transactions see; neither is what a half-applied write breaks.', intro: 'Decide whether the broken promise is about work that was committed or about work that never was.', tags: ['Transactions', 'ACID'] },
  { q: 'The "C" in ACID (Consistency) means:', opts: ['Every replica returns the same value at the same moment', 'A transaction moves the database from one valid state to another, preserving declared constraints', 'Committed changes survive a crash', 'Concurrent transactions cannot see each other\'s partial work'], a: 1, e: 'ACID consistency means a transaction may only commit if every declared rule still holds — foreign keys, unique and check constraints — otherwise it is rejected; the database enforces what you declared and your application is responsible for the invariants you did not. The replica-agreement sense belongs to CAP, a different problem in a different kind of system, and mixing the two is the usual source of confusion. Surviving a crash is durability, and hiding partial work is isolation.', intro: 'CAP uses the same word for something else. Do not let the replica sense answer a question about ACID.', tags: ['Transactions', 'ACID'] },
  { q: 'The "D" in ACID (Durability) guarantees:', opts: ['Committed changes survive a crash or power loss', 'A transaction that has started will eventually commit', 'Every write reaches all replicas before the commit returns', 'Reads are answered from disk rather than from cache'], a: 0, e: 'Durability means that once COMMIT returns, the change is recoverable: PostgreSQL flushes the write-ahead log record to stable storage first, so recovery replays it after a crash. It promises nothing about a transaction succeeding, since any transaction may still roll back, and nothing about replicas, which is synchronous replication and a separate setting. It also says nothing about where a read is served from: a durable commit can perfectly well be read out of cache.', intro: 'The promise starts the moment COMMIT returns — work out what it does and does not cover after that point.', tags: ['Transactions', 'ACID'] },
  { q: 'Which command makes a transaction’s changes permanent?', opts: ['ROLLBACK', 'COMMIT', 'SAVEPOINT', 'RELEASE SAVEPOINT'], a: 1, e: 'COMMIT ends the transaction and makes its changes permanent and visible to other sessions, and PostgreSQL flushes the write-ahead log record first so the work survives a crash from that moment. ROLLBACK ends it the other way, discarding everything since BEGIN. SAVEPOINT and RELEASE SAVEPOINT only manage markers inside an open transaction: neither ends it and neither makes anything permanent, which is why a SAVEPOINT is not a partial commit.', intro: 'All four are real SQL statements, so decide by what each does to the open transaction rather than by which looks unfamiliar.', tags: ['Transactions', 'commit'] },
  { q: 'Why wrap "debit one account, credit another" in a transaction?', opts: ['So the two updates run faster than two separate statements', 'So money is never lost or created: both updates apply or neither does', 'So the two rows stay locked for the rest of the session', 'So a failed update is retried automatically until it succeeds'], a: 1, e: 'Without a transaction, an error or crash between the debit and the credit leaves the money withdrawn from one account and never added to the other, and no later query can tell that anything is missing. Inside one transaction the pair commits together or rolls back together, so no observer ever sees half a transfer. Grouping does not make the statements faster, it does not retry anything for you, and the row locks it takes are released at commit rather than held for the session.', intro: 'Imagine the process dying between the two statements and ask who is out of pocket.', tags: ['Transactions', 'atomicity'] },
  { q: 'ROLLBACK is used when:', opts: ['You want to keep changes', 'An error occurs and you want to undo the transaction’s changes', 'You want to index a table', 'You want to commit faster'], a: 1, e: 'ROLLBACK aborts the transaction, undoing all its uncommitted changes.', tags: ['Transactions', 'rollback'] },
  { q: 'A SAVEPOINT lets you:', opts: ['Commit part of a transaction while the rest stays open', 'Roll back to a marked point without aborting the whole transaction', 'Keep a transaction open across a lost connection', 'Reserve in advance the rows the transaction will need'], a: 1, e: 'SAVEPOINT names a point inside an open transaction, and ROLLBACK TO SAVEPOINT undoes the work after it while the transaction keeps running — this is how a driver or ORM recovers from an expected error such as a duplicate key without losing everything done so far. It commits nothing: no work is durable or visible to other sessions until the transaction itself commits. It also does not survive a lost connection, which rolls the whole transaction back, and it reserves no rows in advance.', intro: 'Ask whether the marker can make work permanent, or only undo back to itself.', tags: ['Transactions', 'savepoint'] },

  // Level 12 — Isolation & Locking
  { q: 'Isolation levels control:', opts: ['How long a transaction may run before the server cancels it', 'Which anomalies concurrent transactions may observe in each other\'s data', 'How many transactions may run at the same time', 'Whether one transaction may write to more than one table'], a: 1, e: 'An isolation level is a contract about which concurrency anomalies are permitted — dirty reads, non-repeatable reads, phantoms, serialization anomalies — and so about how much of a neighbor\'s work a transaction can see. Stricter is not simply better: in PostgreSQL, Repeatable Read and Serializable turn some conflicts into errors with SQLSTATE 40001 that the application has to retry, which is the price of removing the anomaly. The level caps neither how many transactions run nor how long they may run, and it never limits which tables they touch.', intro: 'Ask which of these actually changes when you move from READ COMMITTED to SERIALIZABLE.', tags: ['Transactions', 'isolation'] },
  { q: 'A "dirty read" is:', opts: ['Reading a row that another transaction committed a moment earlier', 'Reading another transaction\'s uncommitted changes, which may still be rolled back', 'Reading the same row twice in one transaction and getting different values', 'Reading a row while another transaction holds a lock on it'], a: 1, e: 'A dirty read sees a row written by a transaction that has not committed, so the value can vanish when that transaction rolls back and any decision made on it rested on data that never existed. Reading the same row twice and getting different committed values is a non-repeatable read — a weaker anomaly, and one PostgreSQL does allow at Read Committed. Worth knowing when you read the level table: PostgreSQL never produces dirty reads, because a request for READ UNCOMMITTED is treated as READ COMMITTED.', intro: 'Focus on whether the writing transaction has finished, not on how many times you read.', tags: ['Transactions', 'anomalies'] },
  { q: 'Which isolation level prevents dirty reads but may allow non-repeatable reads?', opts: ['READ UNCOMMITTED', 'READ COMMITTED', 'REPEATABLE READ', 'SERIALIZABLE'], a: 1, e: 'READ COMMITTED, PostgreSQL\'s default, gives each statement a fresh snapshot of committed data: no dirty reads, but a row read twice in one transaction can differ because another transaction committed in between. READ UNCOMMITTED is the standard level that permits dirty reads, although PostgreSQL treats a request for it as READ COMMITTED. REPEATABLE READ and SERIALIZABLE hold one snapshot for the whole transaction, so they exclude non-repeatable reads too and are stronger than the question asks for.', intro: 'Each level is defined as much by what it still allows as by what it blocks. Check both halves.', tags: ['Transactions', 'isolation'] },
  { q: 'The strongest standard isolation level is:', opts: ['READ UNCOMMITTED', 'READ COMMITTED', 'REPEATABLE READ', 'SERIALIZABLE'], a: 3, e: 'SERIALIZABLE is the strongest of the four standard levels: concurrent transactions must produce a result that some serial order of them would have produced, so no standard anomaly is possible. The levels below it permit progressively more: REPEATABLE READ the least, then READ COMMITTED (PostgreSQL\'s default), then READ UNCOMMITTED the most. The strength is not free: PostgreSQL enforces it by aborting transactions with a serialization failure, SQLSTATE 40001, so any application running at this level has to retry the whole transaction.', intro: 'Compare what each level still permits; the strongest has nothing left on its row of the anomaly table.', tags: ['Transactions', 'isolation'] },
  { q: 'A deadlock occurs when:', opts: ['A transaction waits for a lock held by a long-running query', 'Two transactions each hold a lock the other needs, so neither can proceed', 'A query runs long enough to hit the statement timeout', 'So many transactions queue for one row that throughput collapses'], a: 1, e: 'A deadlock is a cycle: A holds a lock B needs while B holds a lock A needs, so no amount of waiting helps. PostgreSQL detects the cycle and aborts one of the transactions so the other can finish, which means the application has to be ready to retry the loser. Plain lock waiting is not a deadlock — it clears when the holder commits — and a statement timeout or a queue on one hot row is congestion; the standard prevention is for all code paths to take locks in the same order.', intro: 'Work out which transaction is waiting for which in each of these situations.', tags: ['Transactions', 'deadlock'] },
  { q: 'SELECT ... FOR UPDATE is used to:', opts: ['Read the selected rows without taking any lock, for speed', 'Lock the selected rows so other transactions cannot modify them until you commit', 'Rewrite the selected rows with the values they already hold', 'Reserve the next id values the table will generate'], a: 1, e: 'FOR UPDATE locks every row the SELECT returns and holds the lock until the transaction ends, so any concurrent UPDATE, DELETE or FOR UPDATE on those rows waits. That is what makes read-modify-write safe: read the balance, decide, write it back, with nobody changing it in between. The cost is real — other transactions block, and locks taken in different orders by different code paths deadlock — so lock as few rows as late as you can, and use FOR UPDATE SKIP LOCKED for queue-style workloads where waiting is pointless.', intro: 'Ask what has to stay true between your read and your write for the decision you made to still hold.', tags: ['Transactions', 'locking'] },
  { q: 'Optimistic concurrency control typically:', opts: ['Locks the rows up front so no one else can touch them', 'Lets transactions proceed and checks at write time whether the row changed, using a version column', 'Serializes all writers through a single queue so conflicts cannot arise', 'Keeps a copy of every row so conflicting writes can be merged automatically'], a: 1, e: 'Optimistic control assumes conflicts are rare: you read the row together with its version, and the UPDATE carries WHERE version = the value you read, so it matches zero rows when someone got there first and you retry or report the conflict. Nothing is locked between the read and the write, which is what makes it right for long think-time, such as a user editing a form, where a pessimistic lock would be held for minutes. The trade is wasted work on retry, and nothing merges two edits for you — you still have to decide who wins.', intro: 'Ask when the conflict is discovered: before the work starts, or when the write lands.', tags: ['Transactions', 'concurrency'] },
  { q: 'A "lost update" anomaly happens when:', opts: ['Two transactions read a value and both write it back, so one update disappears', 'A transaction reads a row whose writer later rolls back', 'A transaction reads the same row twice and sees two different committed values', 'A transaction\'s committed changes are never flushed to disk'], a: 0, e: 'Two read-modify-write transactions interleave: both read a counter of 10, both write 11, and one increment is gone with no error raised. At Read Committed you have to prevent it yourself, with SELECT ... FOR UPDATE, a version check in the WHERE clause, or an atomic UPDATE ... SET n = n + 1; in PostgreSQL, Repeatable Read and Serializable instead abort one of the transactions with a serialization failure that you retry. Reading a writer\'s rolled-back data is a dirty read and seeing two different committed values is a non-repeatable read; both are read anomalies, whereas here a write is lost.', intro: 'Both transactions succeed and no error appears anywhere — ask what became of the first one\'s work.', tags: ['Transactions', 'anomalies'] },

  // Level 13 — The N+1 Problem
  { q: 'The "N+1 query problem" is:', opts: ['One query that returns one row more than the requested page size', 'One query for a list, then one extra query per item to load related data', 'One query repeated because the connection pool retried it', 'One join that multiplies rows so the result is many times too large'], a: 1, e: 'N+1 names the shape: one query returns N rows, then the code loops and issues one more query per row, so the database sees N+1 statements where one or two would do. The cost is round trips, and each individual query is fast, which is why the pattern passes review and only appears as latency once N is large. A join that multiplies rows is the opposite failure, a fan-out, and a retried query is a connection problem rather than a query pattern.', intro: 'Count the statements the database receives while the loop runs, not how long each one takes.', tags: ['N+1', 'performance'] },
  { q: 'Fetching 100 posts then querying each post’s author separately causes:', opts: ['100 queries', '101 queries', '2 queries', '1 query'], a: 1, e: 'One query fetches the 100 posts and the loop then issues one query per post for its author: 100 + 1 = 101 statements and 101 round trips. Answering 100 is the off-by-one hiding in the name — the list query counts too. The other two numbers are the fixes rather than the problem: two queries is the batched form (fetch the posts, then all their authors with a single WHERE id IN (...)), and one query is a JOIN.', intro: 'List the statements this request sends, in the order they are sent, then count them.', tags: ['N+1', 'performance'] },
  { q: 'A common fix for N+1 is to:', opts: ['Add an index to the child table so each per-item query is fast', 'Load the related rows in one JOIN or one batched WHERE id IN (...) query', 'Cache each per-item query result so repeated lookups are cheap', 'Raise the connection pool size so the per-item queries run in parallel'], a: 1, e: 'The cost is the number of round trips, so the fix is to fetch the related rows together: a JOIN, or a second query with WHERE id IN (...) built from the ids you already hold. Indexing, caching and a larger pool make each of the N queries cheaper or more parallel but leave N of them, so latency still grows with the list. The two shapes trade against each other: a JOIN repeats the parent columns once per child and can fan out badly on one-to-many, while the batched query costs one extra round trip and stitches the rows together in application code.', intro: 'Ask what grows as the list gets longer: the time per query, or the number of queries.', tags: ['N+1', 'joins'] },
  { q: 'In ORMs, "eager loading" (e.g. includes/joins) helps by:', opts: ['Deferring each relation\'s query until the field is first read', 'Fetching the related records up front, so no per-item query is needed', 'Keeping related records in a process-level cache between requests', 'Turning the relation into a database view the ORM maintains'], a: 1, e: 'Eager loading tells the ORM to fetch the associations alongside the parent rows, as one JOIN or one batched query, so the loop that follows touches the database no further. Lazy loading is the default that produces N+1: each association is queried the first time it is read, once per object. It is not free either — eager-loading a relation the page never renders pulls rows and columns nobody uses — so enable it per query rather than globally on the model.', intro: 'Ask when the related rows are fetched: before the loop runs, or the first time each one is touched.', tags: ['N+1', 'orm'] },
  { q: 'Why is N+1 often invisible in development but painful in production?', opts: ['Development databases hold more rows than production', 'With small dev data the extra queries are cheap; at scale the per-row queries dominate latency', 'The pattern only affects writes, and development workloads mostly read', 'The planner rewrites the loop into a join once table statistics exist'], a: 1, e: 'With ten rows in development the eleven queries finish in milliseconds and nothing looks wrong. In production the same code runs over thousands of rows, and the cost is one round trip per row — per-statement and network overhead that no index removes, because each of those queries is already using an index and is already fast. That is also why it is found by counting statements per request in a query log or APM rather than in the slow-query log, where every one of them looks healthy.', intro: 'Ask what differs between your development database and production, and what that difference does to N.', tags: ['N+1', 'scaling'] },
  { q: 'A "DataLoader"-style batching utility addresses N+1 by:', opts: ['Caching every table in memory when the process starts', 'Collecting individual key lookups within a tick and issuing one batched query', 'Rewriting each resolver\'s query into a JOIN before it runs', 'Holding the request open until the database reports it is idle'], a: 1, e: 'A DataLoader wraps a batch function: every load(key) call made within the same tick of the event loop is coalesced into one array of keys, so a hundred resolver calls become one WHERE id IN (...). It also memoizes by key for the life of the request, so repeated lookups of the same author cost nothing more. It is not a global cache and it rewrites nothing — you still write the batch query, and it must return values in the same order as the keys it was handed, which is the usual source of mismatched results.', intro: 'The individual lookups are not sent as they arrive — ask what happens in between.', tags: ['N+1', 'batching'] },
  { q: 'Which tool best reveals an N+1 problem?', opts: ['The slow-query log, which lists statements over the time threshold', 'A query log or APM trace showing how many statements one request issued', 'EXPLAIN ANALYZE run on the list query', 'A database CPU graph for the last hour'], a: 1, e: 'N+1 shows up as a count rather than a duration — one request issuing a hundred near-identical statements — so the tool that finds it is the one that attributes statements to a request: a query log or an APM trace. The slow-query log misses it because every one of those statements is under the threshold. EXPLAIN ANALYZE describes a single statement and cannot see the other hundred, and a CPU graph shows the symptom with nothing to attribute it to.', intro: 'Ask which unit each tool measures: a single statement, one request, or the whole server.', tags: ['N+1', 'observability'] },
  { q: 'A risk of over-eager joining everything to avoid N+1 is:', opts: ['The planner refuses joins beyond a fixed number of tables', 'Large result sets, with parent columns multiplied across every combination of joined child rows', 'Foreign keys stop being enforced while a join runs', 'Every joined table must be indexed or the join fails'], a: 1, e: 'Joining one parent to two one-to-many children multiplies them: 10 parents with 20 comments and 5 tags each return 1000 rows, every one repeating the parent columns, and the application then has to de-duplicate what it asked for. Even a single join over-fetches when the response never renders the related data. So eager loading is a per-query judgment — join what the response needs, batch the rest in a second query, and look at the row count the database actually returned.', intro: 'Work out how many rows come back when each of ten parents has twenty comments and five tags.', tags: ['N+1', 'tradeoffs'] },

  // Level 14 — NoSQL & When to Use It
  { q: 'A document database (e.g. MongoDB) stores data as:', opts: ['Rows in fixed tables', 'Flexible, often JSON-like documents', 'Only key-value pairs', 'Graphs of nodes/edges'], a: 1, e: 'A document store keeps each record as one self-contained JSON-like document — BSON in MongoDB — so nested objects and arrays live inside the record and two documents in the same collection need not carry the same fields. That is the contrast with rows in fixed tables, where the columns are declared once for every row. A pure key-value store hands back an opaque value you cannot query inside, and a graph database makes the edges between records the thing you traverse.', intro: 'Ask what a single record looks like in each model, and whether its shape is fixed in advance.', tags: ['NoSQL', 'document'] },
  { q: 'A key-value store (e.g. Redis) is ideal for:', opts: ['Complex multi-table joins', 'Fast lookups by key, caching, and ephemeral data', 'Strong relational constraints', 'Ad-hoc analytical SQL'], a: 1, e: 'A key-value store answers \'give me the value at this key\' in constant time and little else, which is exactly the shape of a cache, a session, a rate-limit counter or a job queue. The limit is the other side of that: no joins, no constraint tying two keys together, and no ad-hoc filtering over values unless you build a secondary index yourself, so anything relational stays in the relational database. Redis holds more than plain strings, including hashes, lists, sets, sorted sets and streams with per-key expiry, but every one of them is still reached by key.', intro: 'Ask which questions you can still answer when the only thing you know is the key.', tags: ['NoSQL', 'key-value'] },
  { q: 'A graph database is best suited to:', opts: ['Reporting that aggregates one large table by month', 'Highly connected data where a query follows relationships several hops deep', 'Storing large binary files such as images and video', 'Counting events against a single incrementing key'], a: 1, e: 'A graph database stores edges as first-class records, so a traversal such as \'friends of friends who bought this\' follows pointers and its cost tracks the part of the graph visited. The same question in SQL needs one self-join per hop, or a recursive CTE when the depth varies, and the cost climbs with depth either way; that is the deciding factor, not the data being \'connected\' in the abstract. Aggregating one table by month is ordinary SQL, large binaries belong in object storage, and a single counter belongs in a key-value store.', intro: 'Ask what each of these workloads would cost in an ordinary relational database.', tags: ['NoSQL', 'graph'] },
  { q: '"Schema-less" in NoSQL really means:', opts: ['Documents in a collection have no structure at all', 'The structure is flexible and enforced by the application rather than the database', 'The database infers a fixed schema from the first document written', 'Fields may be added to a document but never removed'], a: 1, e: 'Documents in one collection may carry different fields, so the database accepts a record whether or not it matches its neighbors; the shape is still real, it is simply enforced by your code and by whatever validation you configure. That moves the work rather than removing it: every old shape stays in the collection, each reader has to tolerate it, and a migration becomes a backfill you write and run yourself. MongoDB does offer optional schema validation, and each document still needs its _id, so this is flexibility rather than an absence of structure.', intro: 'Ask what happens when a document arrives missing a field its neighbors have, and who notices.', tags: ['NoSQL', 'schema'] },
  { q: 'A reason to choose a relational DB over NoSQL is:', opts: ['The document shapes change constantly and you want to avoid migrations', 'You need joins across several entities, constraints the engine enforces, and transactions spanning rows', 'Every access is a lookup by a single known key', 'You need to store more data than one machine can hold'], a: 1, e: 'A relational database is the one that gives you joins over arbitrary entities, constraints the engine itself enforces, and transactions across many rows, with a planner deciding how to execute them. The alternatives win when the access pattern is narrower — a lookup by known key, or documents whose shape keeps changing — or when the data outgrows a single machine. Treat this as a default rather than a law: MongoDB has supported multi-document transactions on replica sets since 4.0, and PostgreSQL stores and indexes JSON, so both sides have moved toward the middle.', intro: 'Ask what you would have to reimplement in application code if you picked the other kind of store.', tags: ['NoSQL', 'tradeoffs'] },
  { q: 'Under CAP, a distributed database that keeps accepting writes on both sides of a network partition has chosen:', opts: ['Consistency over availability', 'Availability over consistency, with the replicas converging afterward', 'Durability over consistency', 'Partition tolerance over durability'], a: 1, e: 'CAP describes what a system does during a partition: either it refuses requests on the side that cannot confirm the current state (CP) or it answers anyway and reconciles later (AP). Accepting writes on both sides means the replicas can disagree until they converge, which is what eventual consistency means. Durability is not part of the trade — both kinds still persist what they accept — and partition tolerance is not optional for anything spanning machines. Do not reduce this to \'SQL is CP, NoSQL is AP\': MongoDB replica sets elect one primary and refuse writes on the minority side, while Cassandra and DynamoDB default to the availability side.', intro: 'The choice only exists while the two sides cannot reach each other.', tags: ['NoSQL', 'consistency'] },
  { q: 'Denormalizing/embedding related data in a document is common in NoSQL because:', opts: ['Joins across collections are cheaper than reading a single document', 'The document can be read in one fetch, with no second query per related record', 'Embedding is what keeps the data in third normal form', 'The database rejects documents that reference another collection'], a: 1, e: 'Embedding puts everything one request needs into a single document, so the read is one fetch by key with no follow-up query per related record — that, not the absence of joins, is the reason. MongoDB does have $lookup, but cross-collection joins are not the access pattern the model is tuned for. The cost is duplication: an embedded copy has to be updated everywhere it appears, and an array that grows without bound eventually meets the 16 MiB document limit, so embed what is read together and reference what is large or shared.', intro: 'Count the round trips a page needs under each model before deciding why the shape is chosen.', tags: ['NoSQL', 'modeling'] },
  { q: 'A service keeps its core data in PostgreSQL and the team proposes adding Redis for caching and a search engine for full text. What is the main cost of that split?', opts: ['PostgreSQL queries can no longer use their indexes', 'Each extra store is more to operate, and data held in two places can disagree', 'PostgreSQL cannot run alongside another database', 'Transactions inside PostgreSQL stop being atomic'], a: 1, e: 'Polyglot persistence — matching the store to the workload — is a real technique, because a cache and a search index each do something a relational database does slowly. The cost is that every extra store is another thing to run, back up, monitor, secure and upgrade, and no transaction spans two of them, so a write that lands in one and fails in the other leaves them disagreeing until something reconciles them. That is why the sensible default is to push PostgreSQL until a workload genuinely does not fit; nothing in the split changes how PostgreSQL plans queries or how its own transactions behave.', intro: 'Ask what the team owns after the split that it did not own before.', tags: ['NoSQL', 'architecture'] },

  // Level 15 — Performance & Scaling
  { q: 'Read replicas primarily help by:', opts: ['Increasing write throughput, since writes are spread across the copies', 'Spreading read load across copies, while writes still go to the primary', 'Removing the need for indexes on the primary', 'Guaranteeing that a read always sees the write that just committed'], a: 1, e: 'A replica keeps a copy of the primary\'s data and can answer SELECTs, so read-heavy traffic spreads over several machines. Writes gain nothing: they all still go to the primary and are then shipped to every replica, so adding replicas adds work on the write path rather than capacity. The trade is lag — a replica applies changes slightly behind the primary — so a read issued right after a write can miss it, which is why read-your-own-writes paths are routed back to the primary.', intro: 'Follow a write and a read separately: only one of them gains extra machines to go to.', tags: ['Scaling', 'replication'] },
  { q: 'Connection pooling improves performance by:', opts: ['Compressing the data sent over each connection', 'Reusing a limited set of established connections instead of opening one per request', 'Giving every query its own fresh connection for isolation', 'Caching query results so repeated queries skip the database'], a: 1, e: 'Opening a PostgreSQL connection costs a TCP handshake, authentication and a new server-side backend process, which is far more than most queries cost; a pool keeps a few open and lends them out. The cap matters as much as the reuse, because each connection consumes memory on the server, so the pool is also what stops a traffic spike from opening thousands of them. That is why serverless and multi-instance deployments usually add a pooler such as PgBouncer in front: many small instances, each with its own pool, can still exhaust the server.', intro: 'Ask what a request pays before its first query runs, and what happens when a thousand requests arrive at once.', tags: ['Scaling', 'pooling'] },
  { q: 'Caching frequent query results (e.g. in Redis) helps when:', opts: ['The value changes on almost every request', 'Reads vastly outnumber writes and slightly stale data is acceptable', 'Every read has to reflect the most recent committed write', 'The query already answers from a small table in under a millisecond'], a: 1, e: 'A cache pays off when the same value is read far more often than it changes and a reader can tolerate the previous value for a while. Both halves matter: a value that changes on nearly every request is never reused, and a path that must see the newest committed write cannot accept a stale copy at all. The cost is invalidation — every write now has a second place to update or expire — so cache the few hot, read-mostly values with a TTL you can defend rather than caching everything.', intro: 'A cached value is a promise that the real one has not changed since. Ask when that promise is safe.', tags: ['Scaling', 'caching'] },
  { q: 'Horizontal partitioning (sharding) splits a table by:', opts: ['Columns, so each server stores a different set of fields', 'Rows, so each server stores a subset chosen by a shard key', 'Indexes, so each server stores a different index of the same table', 'Queries, so each server runs a different part of the workload'], a: 1, e: 'Sharding cuts horizontally: each server holds a subset of the rows, chosen by hashing or ranging a shard key, so storage and load both grow beyond one machine. Cutting by columns is vertical partitioning, a different technique for different reasons. The cost is that the shard key then governs everything — a query without it fans out to every shard, joins across shards are yours to implement, and changing the key later means moving data — so shard only when one machine genuinely cannot carry the workload.', intro: 'Horizontal and vertical name the direction of the cut — decide which way this one runs.', tags: ['Scaling', 'sharding'] },
  { q: 'A poorly chosen shard key can cause:', opts: ['Every shard receiving an equal share of reads and writes', 'Hot spots, where one shard receives most of the traffic', 'Queries that carry the shard key having to visit every shard', 'The database refusing writes until the key is changed'], a: 1, e: 'A shard key with low cardinality, such as a status column, or a monotonically increasing one, such as a timestamp or auto-increment id, sends most traffic to a single shard: that node saturates while the rest idle and the cluster performs like one smaller machine. A well-spread key distributes storage and load together. Queries that do carry the shard key are routed to one shard — it is queries without it that fan out to all of them — and no engine refuses writes over a poor key; it simply gets slow.', intro: 'Picture a key whose values are nearly all the same, or one that only ever increases.', tags: ['Scaling', 'sharding'] },
  { q: 'A frequent root cause of a slow endpoint is:', opts: ['Too many indexes only', 'A missing index causing a full scan, or an N+1 query pattern', 'Using a primary key', 'Committing transactions'], a: 1, e: 'Missing indexes and N+1 patterns are the usual suspects behind slow data access; profile with EXPLAIN and query logs.', tags: ['Scaling', 'performance'] },
  { q: 'Pagination with large OFFSET values is slow because:', opts: ['The database re-sorts the whole result set for every page requested', 'The database still computes and discards every skipped row', 'OFFSET takes a table lock while it counts rows', 'OFFSET stops the query from using any index'], a: 1, e: 'OFFSET does not skip work: the server still computes the skipped rows in order and throws them away, so page 1000 costs roughly a thousand times page 1. Sorting is not the part that grows, because the same ORDER BY costs the same whether you ask for page 1 or page 1000, while the rows produced and discarded grow with the offset. Keyset (seek) pagination replaces it with WHERE (created_at, id) < (last_seen_values) ORDER BY created_at DESC, id DESC LIMIT n, which starts at the right place in the index and stays flat as the page number grows. What you give up is arbitrary jumps: keyset moves forward and back from a known row, not straight to page 500, and it needs a sort key that is unique and stable.', intro: 'Compare what page 2 and page 1000 each ask the server to do.', tags: ['Scaling', 'pagination'] },
  { q: 'Before optimizing a query, you should first:', opts: ['Add an index on every column the query filters or sorts by', 'Measure: read the plan with EXPLAIN and confirm where the time actually goes', 'Cache the endpoint\'s response so the query runs less often', 'Move the query to a read replica to take load off the primary'], a: 1, e: 'EXPLAIN ANALYZE shows which node of the plan consumes the time and whether the planner\'s row estimates match reality, so the change you make addresses the actual cost instead of a guess. The other three are real techniques applied blind: indexing every filtered column slows writes and may produce indexes the planner never uses, caching hides a query that is quietly getting worse, and a replica moves load without making anything faster while adding replication lag. Measure, change one thing, then measure again.', intro: 'You do not yet know which part of the request is slow; decide what to do about that first.', tags: ['Scaling', 'optimization'] },
];
